sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var espaco = g_form.getValue('espaco');
   var dataInicio = g_form.getValue('data_inicio');
   var dataFim = g_form.getValue('data_fim');

   if (!espaco || !dataInicio || !dataFim) {
      return;
   }

   var ga = new GlideAjax('ReservaAjaxUtils');
   ga.addParam('sysparm_name', 'verificarDisponibilidadeEspaco');
   ga.addParam('sysparm_espaco', espaco);
   ga.addParam('sysparm_data_inicio', dataInicio);
   ga.addParam('sysparm_data_fim', dataFim);
   ga.addParam('sysparm_sys_id', g_form.getUniqueValue());

   ga.getXMLAnswer(function(resposta) {
        if (resposta === 'true') {
            g_form.clearMessages();
            g_form.addErrorMessage('⚠ Atenção: Este espaço já possui uma reserva que entra em conflito com este horário.');
            g_form.showFieldMsg(control.name, 'Conflito detectado', 'error');
            g_form.clearValue(control.name); // Esvazia o campo e impede o Submit
        } else {
            g_form.clearMessages();
            g_form.hideFieldMsg(control.name);
        }
    });
}
